insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-0','app-faq.md','Bill Bachao app FAQ','How do I read my prepaid meter?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','From the Bill Bachao app FAQ: practical guidance on photographing a prepaid electricity meter so the app can read the balance or total kWh.','Most prepaid meters cycle through several screens. Photograph the screen that shows the remaining balance in taka or the total kWh used. Hold the phone straight, avoid glare, and make sure all digits are sharp. Bill Bachao reads the digits; if it is not sure, it asks you to confirm.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-1','app-faq.md','Bill Bachao app FAQ','What is the home twin?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','From the Bill Bachao app FAQ: explains the home twin, which estimates base load versus cooling from nameplates and later from meter readings and temperature.','The home twin is a small model of your home''s electricity use. At first it uses your appliances'' nameplate watts and hours. After seven or more meter readings it learns how much your use rises on hot days, so it can split your bill into base load and cooling.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-2','app-faq.md','Bill Bachao app FAQ','What is Slab Guard?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','From the Bill Bachao app FAQ: explains Slab Guard, the month-end unit forecast that warns before crossing a costlier tariff block such as 400 units.','Slab Guard projects how many units you will use by the end of the month and warns you before you cross into a more expensive tariff block, especially the jump above 400 units. It also shows the smallest change, such as raising the AC by one or two degrees, that keeps you under.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-3','app-faq.md','Bill Bachao app FAQ','Why does my bill go up so much in summer?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','From the Bill Bachao app FAQ: why summer electricity bills in Bangladesh rise faster than usage, because of fans, ACs and progressive tariff blocks.','In summer, fans and air conditioners run for many more hours. More units push you into higher tariff blocks, so the extra units cost more than the first ones. Above 400 units each extra unit costs Tk 15.01 instead of Tk 9.62.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-4','app-faq.md','Bill Bachao app FAQ','Is my data safe?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','From the Bill Bachao app FAQ: how household data is protected with per-purpose consent and per-household access.','You choose what to share for each purpose: photos, AI chat, peak challenges and offers. Each household sees only its own data. Partners such as electricity distributors see only area totals.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-5','app-faq.md','Bill Bachao app FAQ','বিল বাঁচাও কী?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','Bangla FAQ entry describing what Bill Bachao does: forecasting month-end units from a meter photo and warning before a costlier slab.','বিল বাঁচাও মিটারের একটি ছবি থেকে আপনার বিদ্যুৎ বিল কমাতে সাহায্য করে। এটি মাসের শেষে কত ইউনিট হবে তা অনুমান করে এবং বেশি দামের স্ল্যাবে যাওয়ার আগে সতর্ক করে।');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('app-faq-6','app-faq.md','Bill Bachao app FAQ','৪০০ ইউনিটের পরে দাম কত?','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/app-faq.md','Bangla FAQ entry giving the June 2026 residential price above 400 units (Tk 15.01) versus 301-400 units (Tk 9.62).','জুন ২০২৬ থেকে ৪০০ ইউনিটের পরের প্রতিটি ইউনিটের দাম ১৫.০১ টাকা, আর ৩০১ থেকে ৪০০ ইউনিট পর্যন্ত ৯.৬২ টাকা।');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-7','cooling.md','Air conditioners, fans and the summer peak','Why cooling drives the evening peak','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling and the summer peak in Bangladesh: seasonal demand figures and the 9 PM peak of 19,027 MW on 27 August 2026 reported by IEEFA.','Bangladesh''s electricity demand roughly doubles from winter to summer. In February 2025 the power adviser said winter demand is around 9,000 MW but summer demand rises to 17,000-18,000 MW (banglanews24). IEEFA reported that on 27 August 2026 demand peaked at 19,027 MW at 9 PM, and that household fan use peaks around 9 PM.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-8','cooling.md','Air conditioners, fans and the summer peak','How much power air conditioners use','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling: official estimates of how many megawatts air conditioners add to Bangladesh''s summer demand and the savings from a 25 C setting.','Government officials estimated that air conditioners account for about 5,000-6,000 MW of summer demand, and said setting thermostats to 25 C could save 2,000-3,000 MW (banglanews24, February 2025). Another statement put AC load at 4,000-5,000 MW with about 2,000 MW of possible savings (The Business Standard).');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-9','cooling.md','Air conditioners, fans and the summer peak','The 25 C advice','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling: the Cabinet Division''s voluntary request to keep ACs at 25 C or higher, and how Bill Bachao turns it into a measured challenge.','The Cabinet Division asked government and private offices and households to keep air conditioners at 25 C or higher (Dhaka Tribune). It is a voluntary appeal: nobody measures or rewards who follows it. Bill Bachao turns it into a measured, optional challenge.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-10','cooling.md','Air conditioners, fans and the summer peak','How much one degree saves','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling: the estimated energy saved per degree of AC set-point increase (up to about 6 percent) and the 3-6 percent range Bill Bachao uses.','A Daily Star opinion piece reported that raising the AC thermostat by 1 C can save up to about 6 percent of AC energy. Bill Bachao uses a cautious range of 3 to 6 percent per degree and always shows savings as a range, not one exact number.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-11','cooling.md','Air conditioners, fans and the summer peak','Efficient fans','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling: IEEFA''s estimates of fan load in summer demand and the peak savings possible from efficient BLDC fans.','IEEFA estimated that household fans add up to 5,212 MW to summer demand, that energy-efficient BLDC fans are less than 2 percent of household fans, and that replacing old fans with BLDC models could cut summer peak demand by up to 2,590 MW (IEEFA, November 2026).');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('cooling-12','cooling.md','Air conditioners, fans and the summer peak','Inverter air conditioners','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on cooling: how inverter air conditioners save energy and how Bill Bachao estimates upgrade payback.','Inverter ACs adjust compressor speed instead of switching fully on and off, so they usually use less electricity for the same cooling. Bill Bachao''s upgrade advisor compares nameplate watts and the user''s tariff to estimate payback months.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('peak-13','peak.md','Peak hours, load-shedding and demand response','What the peak is','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on the Bangladesh grid: what the evening peak is, when it happens, and how it leads to load-shedding.','The evening peak is the time of day when the grid carries the most load. In Bangladesh''s summer it falls in the evening, around 7 to 11 PM, with the highest demand around 9 PM (IEEFA). When supply cannot meet the peak, distributors cut power to some areas, which is load-shedding.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('peak-14','peak.md','Peak hours, load-shedding and demand response','Why the peak is expensive','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on the grid: why electricity at the peak is expensive, citing BPDB''s projected average generation cost for 2026-27.','Meeting the last few hundred megawatts at the peak often needs the most expensive power plants. BPDB projected an average generation cost of about Tk 12.91 per unit for fiscal 2026-27 (EP-BD), above most residential tariff blocks, so every unit moved out of the peak helps.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('peak-15','peak.md','Peak hours, load-shedding and demand response','What demand response means','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on the grid: what demand response is and how Bill Bachao verifies it with before-and-after meter photos instead of smart meters.','Demand response means asking users to reduce or shift electricity use for a short time when the grid is stressed, and rewarding them for it. Large programmes usually need smart meters. Bill Bachao does it with phone photos of ordinary meters: a reading before and after the challenge window shows what the home actually used.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('peak-16','peak.md','Peak hours, load-shedding and demand response','Shifting versus saving','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on the grid: the difference between saving energy (AC set-point) and shifting it out of the peak (pump, iron, washing after 11 PM).','Raising the AC set-point saves energy. Running the water pump, iron or washing machine after 11 PM does not save energy but moves it out of the peak. Bill Bachao counts these separately as kWh saved and kWh moved.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('peak-17','peak.md','Peak hours, load-shedding and demand response','Peak Hour Hero','https://ieefa.org/articles/energy-efficient-fans-could-cut-bangladeshs-peak-power-demand-2590mw-ieefa','From notes on the grid: how Bill Bachao''s Peak Hour Hero challenge works for households during the evening peak.','On hot evenings Bill Bachao sends a voluntary challenge for the peak window, for example keeping the AC at 26 or 27 C and running heavy appliances after 11 PM. Users accept with one tap, photograph the meter at the start and end, and earn points. Area totals are shown to partners only as aggregates.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('safety-18','safety.md','Heat safety and fairness rules in Bill Bachao','Safety comes before saving','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/safety.md','From Bill Bachao''s safety rules: challenges never ask for an AC above 27 C or fans off, and are always optional.','Bill Bachao never asks anyone to set an AC above 27 C and never asks anyone to switch fans off. Comfort and health come first; challenges are always optional and saying no costs nothing.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('safety-19','safety.md','Heat safety and fairness rules in Bill Bachao','Homes with vulnerable members','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/safety.md','From Bill Bachao''s safety rules: lower AC limits and no challenges on dangerous-heat nights for homes with elderly, infant, pregnant or ill members.','If a household marks an elderly person, an infant, a pregnant woman or someone who is ill, its AC limit is 26 C. On nights when the heat index is above 41 C, that household receives no challenge at all, only safety tips.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('safety-20','safety.md','Heat safety and fairness rules in Bill Bachao','Lifeline households','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/safety.md','From Bill Bachao''s fairness rules: lifeline households (50 units or less) receive tips but never peak challenges.','Households using 50 units or less a month are lifeline consumers. They receive saving tips but never peak challenges, so the poorest homes do not carry the grid''s problem.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('safety-21','safety.md','Heat safety and fairness rules in Bill Bachao','Signs of heat illness','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/safety.md','From Bill Bachao''s safety rules: warning signs of heat illness and the emergency number 999 in Bangladesh; not medical advice.','Dizziness, confusion, very high body temperature, or stopping sweating in strong heat can be signs of heat illness. Bill Bachao does not give medical advice: in an emergency in Bangladesh call 999 or go to the nearest health centre. Drink water, stay in shade, and keep fans running.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('safety-22','safety.md','Heat safety and fairness rules in Bill Bachao','Privacy rules','https://github.com/mijan-x/bill-bachao/blob/main/knowledge/safety.md','From Bill Bachao''s privacy rules: local redaction of bill photos, no GPS or contacts, and deletion of photos after 30 days.','Bill photos are cleaned of names, addresses and account numbers on the team''s own computer before any cloud model sees them. The app does not collect GPS or contacts; the area is stored at thana level. Photos are deleted after 30 days.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('tariff-23','tariff.md','Residential electricity tariff in Bangladesh (BERC, June 2026)','How the residential slabs work','https://thefinancialexpress.com.bd/views/views/power-tariff-adjustment-alone-will-not-reduce-subsidy-burdens','From notes on the BERC residential tariff effective June 2026: the progressive block rates per unit for each slab.','Residential (LT-A) electricity is billed in progressive blocks. Each block of units in a month is charged at its own rate, so only the units inside a higher block cost more, not the whole bill. From the June 2026 billing cycle the reported rates are: first 75 units Tk 5.26 per unit; units 76 to 200 Tk 8.50; units 201 to 300 Tk 9.10; units 301 to 400 Tk 9.62; units 401 to 600 Tk 15.01; above 600 units a higher top rate applies (Bill Bachao stores Tk 17.35 and asks users to verify it on their bill).
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('tariff-24','tariff.md','Residential electricity tariff in Bangladesh (BERC, June 2026)','The lifeline rate','https://thefinancialexpress.com.bd/views/views/power-tariff-adjustment-alone-will-not-reduce-subsidy-burdens','From notes on the BERC residential tariff: the lifeline rate of Tk 4.63 for households using 50 units or less in a month.','Households whose total use in a month stays at or below 50 units are lifeline consumers. All of their units are billed at the lifeline rate of Tk 4.63 per unit. Going above 50 units moves the household onto the normal blocks.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('tariff-25','tariff.md','Residential electricity tariff in Bangladesh (BERC, June 2026)','The 400-unit jump','https://thefinancialexpress.com.bd/views/views/power-tariff-adjustment-alone-will-not-reduce-subsidy-burdens','From notes on the BERC residential tariff: the price jump above 400 units (Tk 9.62 to Tk 15.01) and why staying under 400 saves money.','The biggest price step is at 400 units. A unit inside the 301-400 block costs Tk 9.62, but every unit above 400 costs Tk 15.01, about 56 percent more. Reporting in August 2026 said many households saw higher bills because rising use pushed them into higher slabs, especially above 600 units. Staying just under 400 units can therefore save a noticeable amount.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('tariff-26','tariff.md','Residential electricity tariff in Bangladesh (BERC, June 2026)','VAT and the demand charge','https://thefinancialexpress.com.bd/views/views/power-tariff-adjustment-alone-will-not-reduce-subsidy-burdens','From notes on the BERC residential tariff: the 5 percent VAT and the demand charge based on sanctioned load.','A 5 percent VAT is added on top of the energy charge. Bills also carry a demand charge based on the sanctioned load in kilowatts; the exact amount is printed on the bill and Bill Bachao lets the user enter it.');
insert into rag_chunks(chunk_key,doc,doc_title,section,source_url,context_prefix,chunk_text) values('tariff-27','tariff.md','Residential electricity tariff in Bangladesh (BERC, June 2026)','How Bill Bachao uses the tariff','https://thefinancialexpress.com.bd/views/views/power-tariff-adjustment-alone-will-not-reduce-subsidy-burdens','From notes on the BERC residential tariff: Bill Bachao calculates bills with a tested function and the AI only explains the result.','Bill Bachao never asks an AI model to calculate a bill. A tested tariff function applies the blocks, the lifeline rule, the demand charge and VAT, and the coach only explains the result.');
